import gurobipy as gp
from gurobipy import GRB
shelves = []
shelf_capacities = {}
products = []
product_values = {}
product_weights = {}
for rec in LEGACY_RECORDS:
    v = rec['values']
    if 'ShelfID' in v and 'Capacity' in v:
        shelf_id = str(v['ShelfID'])
        shelves.append(shelf_id)
        shelf_capacities[shelf_id] = float(v['Capacity'])
    if 'ProductName' in v and 'Value' in v and ('Weight' in v):
        pname = v['ProductName']
        products.append(pname)
        product_values[pname] = float(v['Value'])
        product_weights[pname] = float(v['Weight'])
if len(shelves) == 0 or len(products) == 0:
    raise RuntimeError('Missing shelves or products in LEGACY_RECORDS')
for s in shelves:
    if s not in shelf_capacities:
        raise RuntimeError(f'Missing capacity for shelf {s}')
for p in products:
    if p not in product_values or p not in product_weights:
        raise RuntimeError(f'Missing value or weight for product {p}')
m = gp.Model('Shelf_Product_Allocation')
x = m.addVars(shelves, products, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((product_values[p] * x[s, p] for s in shelves for p in products)), GRB.MAXIMIZE)
m.addConstrs((gp.quicksum((product_weights[p] * x[s, p] for p in products)) <= shelf_capacities[s] for s in shelves), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')